#include <iostream>

constexpr int factorial(int n) {
    return n <= 1 ? 1 : (n * factorial(n - 1));  // Recursive constexpr function; compiler evaluates at compile-time if n is a constant.
}

int main() {
    constexpr int result = factorial(5);  // Compile-time evaluation: Results in 120 at compile-time.
    std::cout << result << std::endl;  // No runtime computation needed for result.
    return 0;
}
